import React, { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { useAuth } from "../../context/AuthContext";
import "../../styles/layout.css";

export default function Navbar({ onSearch }) {
  const { user, logout } = useAuth();
  const navigate = useNavigate();
  const [query, setQuery] = useState("");

  const handleLogout = () => { logout(); navigate("/signin"); };

  return (
    <nav className="navbar">
      <Link className="nav-brand" to="/">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><circle cx="12" cy="12" r="10"/><path d="M8 9h8M8 12h6M8 15h4"/></svg>
        Echo
      </Link>

      <div className="nav-search">
        <input type="text" placeholder="Search posts..." value={query}
          onChange={e => { setQuery(e.target.value); onSearch && onSearch(e.target.value); }} />
      </div>

      <div className="nav-right">
        {user ? (
          <>
            <Link to="/" className="nav-link">Home</Link>
            <Link to="/saved" className="nav-link">Saved</Link>
            {user.role === "admin" && (
              <Link to="/admin" className="nav-link" style={{color:"#ef4444",fontWeight:600}}>🛡️ Admin</Link>
            )}
            {(user.role === "admin" || user.role === "moderator") && (
              <Link to="/moderator" className="nav-link" style={{color:"#8b5cf6",fontWeight:600}}>⚡ Mod</Link>
            )}
            <Link to={`/u/${user.username}`}>
              <div className="nav-avatar" title={user.firstName}>{user.firstName?.[0]?.toUpperCase()}</div>
            </Link>
            <button className="nav-btn ghost" onClick={handleLogout}>Sign out</button>
          </>
        ) : (
          <>
            <Link to="/signin" className="nav-btn outline">Sign in</Link>
            <Link to="/signup" className="nav-btn primary">Sign up</Link>
          </>
        )}
      </div>
    </nav>
  );
}
